-- EXERCÍCIO 6 — PostgreSQL + Orange
-- Base didática com erros intencionais para investigação de qualidade de dados.

DROP VIEW IF EXISTS vw_vendas_analise;
DROP TABLE IF EXISTS vendas;
DROP TABLE IF EXISTS produtos;
DROP TABLE IF EXISTS clientes;

CREATE TABLE clientes (
    id_cliente INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome VARCHAR(100),
    cpf VARCHAR(11),
    email VARCHAR(150),
    telefone VARCHAR(20),
    cidade VARCHAR(80),
    estado CHAR(2),
    data_cadastro DATE NOT NULL
);

CREATE TABLE produtos (
    id_produto INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_produto VARCHAR(120),
    categoria VARCHAR(60),
    preco NUMERIC(10,2),
    ativo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE vendas (
    id_venda INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_cliente INTEGER REFERENCES clientes(id_cliente),
    id_produto INTEGER REFERENCES produtos(id_produto),
    data_venda DATE,
    quantidade INTEGER,
    preco_unitario NUMERIC(10,2),
    desconto_percentual NUMERIC(6,2) DEFAULT 0,
    valor_total NUMERIC(12,2),
    forma_pagamento VARCHAR(30),
    status VARCHAR(20) DEFAULT 'CONCLUIDA'
);

-- 1) CARGA INICIAL CORRETA




-- 2) INTRODUÇÃO PROPOSITAL DE PROBLEMAS
-- Dados vazios (3 registros)
UPDATE clientes SET telefone = NULL WHERE id_cliente = 5;
UPDATE clientes SET email = '' WHERE id_cliente = 12;
UPDATE clientes SET cidade = NULL WHERE id_cliente = 21;

-- Valores inválidos (6 registros)
UPDATE clientes SET email = 'email-invalido' WHERE id_cliente = 7;
UPDATE produtos SET preco = -5.00 WHERE id_produto = 4;
UPDATE vendas SET quantidade = 0 WHERE id_venda = 15;
UPDATE vendas SET quantidade = -2 WHERE id_venda = 27;
UPDATE vendas SET desconto_percentual = 150 WHERE id_venda = 42;
UPDATE vendas SET data_venda = DATE '2099-01-01' WHERE id_venda = 63;

-- Duplicidades lógicas (3 cópias extras; cada caso forma um par com o original)
UPDATE clientes SET cpf = (SELECT cpf FROM clientes WHERE id_cliente = 29) WHERE id_cliente = 30;
UPDATE produtos SET nome_produto = (SELECT nome_produto FROM produtos WHERE id_produto = 9),
                    categoria = (SELECT categoria FROM produtos WHERE id_produto = 9),
                    preco = (SELECT preco FROM produtos WHERE id_produto = 9)
WHERE id_produto = 10;
UPDATE vendas v SET
    id_cliente = x.id_cliente, id_produto = x.id_produto, data_venda = x.data_venda,
    quantidade = x.quantidade, preco_unitario = x.preco_unitario,
    desconto_percentual = x.desconto_percentual, valor_total = x.valor_total,
    forma_pagamento = x.forma_pagamento, status = x.status
FROM vendas x WHERE v.id_venda = 100 AND x.id_venda = 99;

-- Inconsistências (4 registros)
UPDATE vendas SET valor_total = 9999.99 WHERE id_venda = 35;
UPDATE vendas SET preco_unitario = 999.00 WHERE id_venda = 50;
UPDATE clientes SET cidade = 'Curitiba', estado = 'SP' WHERE id_cliente = 16;
UPDATE vendas SET status = 'CANCELADA' WHERE id_venda = 70;

-- View amigável para exploração no Orange
CREATE OR REPLACE VIEW vw_vendas_analise AS
SELECT
    v.id_venda, v.data_venda, v.quantidade, v.preco_unitario,
    v.desconto_percentual, v.valor_total, v.forma_pagamento, v.status,
    c.id_cliente, c.nome AS cliente, c.cpf, c.email, c.telefone, c.cidade, c.estado,
    p.id_produto, p.nome_produto, p.categoria, p.preco AS preco_catalogo, p.ativo,
    ROUND((v.quantidade * v.preco_unitario * (1 - v.desconto_percentual / 100.0))::numeric, 2) AS valor_calculado
FROM vendas v
LEFT JOIN clientes c ON c.id_cliente = v.id_cliente
LEFT JOIN produtos p ON p.id_produto = v.id_produto;

-- Conferência das quantidades solicitadas
SELECT 'clientes' AS tabela, COUNT(*) AS quantidade FROM clientes
UNION ALL SELECT 'produtos', COUNT(*) FROM produtos
UNION ALL SELECT 'vendas', COUNT(*) FROM vendas;
